def solve_problem(m):
    S = list(range(1, m + 1))
    target_sum = m * (m + 1) / 6

    if target_sum != int(target_sum):
        return None, None # Not an integer sum

    T = int(target_sum)

    # 1. Iterate over all non-empty subsets X of S
    for i in range(1, 1 << m):
        X = []
        sum_X = 0
        for j in range(m):
            if (i >> j) & 1:
                X.append(S[j])
                sum_X += S[j]

        if sum_X == T:
            # X is a valid subset. Now check for Y in S \ X

            S_prime = []
            for j in range(m):
                if not ((i >> j) & 1):
                    S_prime.append(S[j])

            m_prime = len(S_prime)

            # 2. Iterate over all non-empty subsets Y of S_prime
            for k in range(1, 1 << m_prime):
                Y = []
                sum_Y = 0
                for l in range(m_prime):
                    if (k >> l) & 1:
                        Y.append(S_prime[l])
                        sum_Y += S_prime[l]

                if sum_Y == T:
                    # Found a solution
                    return X, Y

    return None, None

# Check m from 1 to 15
solutions = {}
print("--- Checking m from 1 to 15 ---")
for m in range(1, 16):
    X, Y = solve_problem(m)
    if X is not None:
        solutions[m] = (X, Y)
        print(f"Found solution for m={m}. X={sorted(X)}, Y={sorted(Y)}")

# Format output for notes
output_notes = "Solutions found for m from 1 to 15:\n"
for m in sorted(solutions.keys()):
    X, Y = solutions[m]
    output_notes += f"m={m}: X={X}, Y={Y}\n"

print("\n--- Formatted Output ---")
print(output_notes)

